50	function applyPlanEffect(effect: Readonly<Record<string, unknown>>, sequence: number): void {
51		const current = probe.plan;
52		if (current === null) throw new TypeError("controlled settlement plan is absent");
53		const entries = Reflect.get(current, "entries") as readonly Readonly<Record<string, unknown>>[];
54		const kind = Reflect.get(effect, "kind");
55		if (kind === "fence") {
56			probe.plan = detachedPlan(
57				Object.freeze({
58					...current,
59					fenceSequence: sequence,
60					revision: (Reflect.get(current, "revision") as number) + 1,
61				})
62			);
63			return;
64		}
65		if (kind !== "replacement") throw new TypeError("controlled settlement effect is invalid");
66		const sourceSequence = Reflect.get(effect, "sourceSequence");
67		const selected = entries.findIndex((entry) => Reflect.get(entry, "sourceSequence") === sourceSequence);
68		if (selected < 0) throw new TypeError("controlled settlement entry is absent");
69		probe.plan = detachedPlan(
70			Object.freeze({
71				...current,
72				entries: Object.freeze(
73					entries.map((entry, index) =>
74						index === selected ? Object.freeze({ ...entry, replacementSequence: sequence }) : entry
75					)
76				),
77				revision: (Reflect.get(current, "revision") as number) + 1,
78			})
79		);
80	}
